<?php /** @var \App\Models\User $u @var array $log */ $sym = (string) setting('currency_symbol', '$'); ?>
<div class="toolbar"><div><b><?= e($u->name) ?></b> <span class="muted"><?= e($u->email) ?></span></div><div class="row-actions"><a class="btn sm ghost" href="<?= e(url('admin/credit')) ?>">← All balances</a><a class="btn sm ghost" href="<?= e(url('admin/orders?q=' . urlencode($u->email))) ?>">Orders</a></div></div>
<div class="cols"><div class="stack wide"><section class="apanel"><h2>Ledger</h2><ul class="timeline"><?php foreach ($log as $l): ?><li><span><?= e($l->reason) ?> <b class="<?= $l->amount < 0 ? 'warn' : 'lime' ?>"><?= ($l->amount > 0 ? '+' : '−') . money(abs($l->amount)) ?></b> <span class="muted">→ <?= money($l->balance) ?></span><?= $l->order_id ? ' · <a href="' . e(url('admin/orders/' . $l->order_id)) . '">order</a>' : '' ?></span><small><?= e($l->actor) ?> · <?= e(fmt_date($l->created_at)) ?></small></li><?php endforeach; ?><?php if (!$log): ?><li class="muted">No activity yet.</li><?php endif; ?></ul></section></div>
<div class="stack"><section class="apanel"><h2>Balance</h2><p style="font:800 34px var(--fd);margin:0" class="lime"><?= money($u->credit) ?></p>
  <form method="post" action="<?= e(url('admin/credit/adjust')) ?>" style="margin-top:14px"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int) $u->id ?>"><input type="hidden" name="back" value="user">
    <div class="g2"><?= field_select('dir', 'Action', ['add' => 'Add', 'remove' => 'Remove'], 'add') ?><?= field_text('amount', 'Amount (' . $sym . ')', '', ['type' => 'number', 'step' => '0.01', 'min' => '0.01', 'required' => true]) ?></div>
    <?= field_text('reason', 'Reason', '', ['placeholder' => 'Goodwill, refund…']) ?><?= field_check('notify', 'Email the customer', true) ?><button class="btn block">Apply</button></form></section></div></div>
